import csv
import io


def parse_csv(raw_csv: str):
    class RecordLines:
        def __init__(self, text):
            self.lines = iter(io.StringIO(text, newline=""))
            self.at_start = True

        def __iter__(self):
            return self

        def __next__(self):
            while True:
                line = next(self.lines)
                if self.at_start:
                    if not line.strip("\r\n") or line.lstrip().startswith("#"):
                        continue
                    self.at_start = False
                return line

    lines = RecordLines(raw_csv.lstrip("\ufeff"))
    reader = csv.reader(lines, delimiter=",", quotechar='"')
    records = []
    old_limit = csv.field_size_limit()
    try:
        csv.field_size_limit(2**31 - 1)
        while True:
            lines.at_start = True
            try:
                record = next(reader)
            except StopIteration:
                break
            if record:
                records.append(record)
    finally:
        csv.field_size_limit(old_limit)

    if not records:
        return {"columns": [], "rows": []}

    columns = records[0]
    rows = records[1:]
    width = max([len(columns)] + [len(row) for row in rows])
    existing = set(columns)
    while len(columns) < width:
        number = len(columns) + 1
        name = "column_" + str(number)
        while name in existing:
            number += 1
            name = "column_" + str(number)
        columns.append(name)
        existing.add(name)

    for row in rows:
        row.extend([""] * (width - len(row)))

    return {"columns": columns, "rows": rows}
